function saveRecord(){const r=S.current;if(!r)return;r.title=$('artTitle').value.trim()||T('untitled');r.titleKey=null;r.inputInfo.photographer=$('photographer').value.trim()||null;r.inputInfo.rights=$('photoRights').value.trim()||null;r.authoredNarrative=$('artNarrative').value;r.observationNote=$('observationNote').value;S.inputInfo=structuredClone(r.inputInfo);persist(r);renderInput();renderRecords();$('recordMeta').textContent=JSON.stringify(metadata(r),null,2);}
function name(v){return v.replace(/[\\/:*?"<>|]/g,'_').slice(0,80)||'Dream';}function download(blob,file){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
async function pack(){if(!S.current)return;saveRecord();$('exportZIP').disabled=true;try{const r=S.current,urls=[{name:'original.png',url:r.input}];for(const[id,frames]of Object.entries(r.frames)){for(const f of frames)urls.push({name:`${id}/step-${f.step}.png`,url:f.url});if(frames.length)urls.push({name:`${id}/final.png`,url:frames.at(-1).url});}const files=await Promise.all(urls.map(async f=>({name:f.name,data:new Uint8Array(await(await fetch(f.url)).arrayBuffer())})));files.push({name:'record.json',data:JSON.stringify(metadata(r),null,2)},{name:'NARRATIVE.txt',data:`${r.personalNarrative.zh}\n\n${r.personalNarrative.en}\n\n${r.authoredNarrative||''}\n\n${r.observationNote||''}`});download(makeZip(files),name(title(r))+'.zip');}catch{toast('exportError');}finally{$('exportZIP').disabled=false;}}
$$('[data-stage]').forEach(b=>b.onclick=()=>stage(b.dataset.stage));$$('[data-go]').forEach(b=>b.onclick=()=>stage(b.dataset.go));$$('[data-case]').forEach(b=>b.onclick=()=>caseTab(b.dataset.case));$('language').onclick=()=>{S.lang=S.lang==='en'?'zh':'en';try{localStorage.setItem('cockroach-language',S.lang);}catch{}translate();};$('guide').onclick=()=>guideStep(0);$('guideNext').onclick=()=>guideStep(S.guide+1);$('guideBack').onclick=()=>guideStep(S.guide-1);$('guideExit').onclick=()=>guideStep(-1);$('flowNext').onclick=()=>{S.flow=(S.flow+1)%6;renderFlow();};$('flowPlay').onclick=()=>{if(S.flowTimer){clearInterval(S.flowTimer);S.flowTimer=null;}else S.flowTimer=setInterval(()=>{S.flow=(S.flow+1)%6;renderFlow();},1500);renderFlow();};
$$('.modelSelect').forEach(e=>e.onchange=()=>change('model',e.value));$$('.targetSelect').forEach(e=>e.onchange=()=>change('target',e.value));$$('.channelSelect').forEach(e=>e.onchange=()=>change('channel',+e.value));$('strength').oninput=e=>change('rate',+e.target.value);$('steps').oninput=e=>change('steps',+e.target.value);$$('.upload').forEach(b=>b.onclick=()=>$('fileInput').click());$('fileInput').onchange=e=>upload(e.target.files[0]);$('inspect').onclick=inspect;$('generate').onclick=()=>generate(false);$('compare').onclick=()=>generate(true);$('replaySaved').onclick=replayEvidence;$('cancel').onclick=()=>{S.cancel=true;S.restart=false;clearTimeout(restartTimer);status('generation','cancelled');};$('playFrames').onclick=()=>{if(S.timer){stopFrames();return;}const max=Math.max(S.frames.baseline.length,S.frames.fineTuned.length);if(max<2){toast('noFrames');return;}if(S.frame===max-1)S.frame=0;$('playFrames').textContent='Ⅱ';S.timer=setInterval(()=>{if(S.frame>=max-1){stopFrames();return;}S.frame++;renderResults();},500);renderResults();};$('timeline').oninput=e=>{stopFrames();S.frame=+e.target.value;renderResults();};$('record').onclick=openRecord;$('closeRecord').onclick=()=>$('recordDialog').close();$('saveRecord').onclick=()=>{saveRecord();toast('saved');};$('exportJSON').onclick=()=>{saveRecord();download(new Blob([JSON.stringify(metadata(S.current),null,2)],{type:'application/json'}),name(title(S.current))+'.json');};$('exportZIP').onclick=pack;$('downloadPNG').onclick=async()=>{try{const r=S.current,frames=r.frames[r.model];download(await(await fetch(frames.at(-1).url)).blob(),name(title(r))+'.png');}catch{toast('exportError');}};$('manifestDownload').onclick=()=>download(new Blob([JSON.stringify(S.dataset,null,2)],{type:'application/json'}),'dataset-manifest.json');document.addEventListener('keydown',e=>{if(e.key==='Escape')guideStep(-1);});
async function json(url){const r=await fetch(url);if(!r.ok)throw new Error(url);return r.json();}
(async()=>{translate();stage('scientist');try{[S.config,S.dataset,S.authors]=await Promise.all([json('experiment/config.json'),json('experiment/dataset-candidates.json'),json('author/manifest.json')]);if(S.config.training){S.run=await json('experiment/run.json');}try{S.evidence=await json('experiment/evidence.json');}catch{}try{S.db=await db();S.records=await allRecords();}catch{toast('storageError');}translate();await loadAuthor(S.authors.records[0]);}catch(e){console.error(e);status('generation','computeError','',true);}})();
